CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TYPE gender AS ENUM ('woman','man','non_binary','other');
CREATE TYPE like_kind AS ENUM ('like','super_like');
CREATE TYPE message_kind AS ENUM ('text','image');
CREATE TYPE subscription_tier AS ENUM ('free','premium');

CREATE TABLE users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email text NOT NULL UNIQUE, phone text UNIQUE, password_hash text NOT NULL, email_verified boolean NOT NULL DEFAULT false, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE profiles (user_id uuid PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, name varchar(80) NOT NULL, birth_date date NOT NULL CHECK (birth_date <= current_date - interval '18 years'), gender gender NOT NULL, city varchar(120) NOT NULL, bio varchar(600) NOT NULL DEFAULT '', dating_goal varchar(40) NOT NULL DEFAULT 'unknown', latitude numeric(9,6), longitude numeric(9,6), online_at timestamptz, hidden boolean NOT NULL DEFAULT false, onboarding_complete boolean NOT NULL DEFAULT false);
CREATE TABLE photos (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, object_key text NOT NULL, position smallint NOT NULL CHECK(position BETWEEN 0 AND 8), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,position));
CREATE TABLE interests (id serial PRIMARY KEY, name varchar(60) NOT NULL UNIQUE);
CREATE TABLE user_interests (user_id uuid REFERENCES users(id) ON DELETE CASCADE, interest_id int REFERENCES interests(id) ON DELETE CASCADE, PRIMARY KEY(user_id,interest_id));
CREATE TABLE preferences (user_id uuid PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, min_age smallint NOT NULL DEFAULT 21 CHECK(min_age>=18), max_age smallint NOT NULL DEFAULT 40 CHECK(max_age>=min_age), max_distance_km smallint NOT NULL DEFAULT 50 CHECK(max_distance_km BETWEEN 1 AND 500), show_genders gender[] NOT NULL DEFAULT ARRAY['woman']::gender[], notifications boolean NOT NULL DEFAULT true);
CREATE TABLE likes (from_user_id uuid REFERENCES users(id) ON DELETE CASCADE, to_user_id uuid REFERENCES users(id) ON DELETE CASCADE, kind like_kind NOT NULL DEFAULT 'like', created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(from_user_id,to_user_id), CHECK(from_user_id<>to_user_id));
CREATE TABLE matches (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_a_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, user_b_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, created_at timestamptz NOT NULL DEFAULT now(), unmatched_at timestamptz, CHECK(user_a_id<user_b_id), UNIQUE(user_a_id,user_b_id));
CREATE TABLE conversations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), match_id uuid UNIQUE REFERENCES matches(id) ON DELETE CASCADE, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE conversation_members (conversation_id uuid REFERENCES conversations(id) ON DELETE CASCADE, user_id uuid REFERENCES users(id) ON DELETE CASCADE, last_read_at timestamptz, PRIMARY KEY(conversation_id,user_id));
CREATE TABLE messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), conversation_id uuid NOT NULL REFERENCES conversations(id) ON DELETE CASCADE, sender_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, kind message_kind NOT NULL DEFAULT 'text', body text, media_key text, reply_to_id uuid REFERENCES messages(id) ON DELETE SET NULL, created_at timestamptz NOT NULL DEFAULT now(), read_at timestamptz, CHECK(body IS NOT NULL OR media_key IS NOT NULL));
CREATE TABLE blocks (blocker_id uuid REFERENCES users(id) ON DELETE CASCADE, blocked_id uuid REFERENCES users(id) ON DELETE CASCADE, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(blocker_id,blocked_id));
CREATE TABLE reports (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), reporter_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, reported_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, reason varchar(80) NOT NULL, details varchar(1000), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE subscriptions (user_id uuid PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, tier subscription_tier NOT NULL DEFAULT 'free', valid_until timestamptz, provider text, external_id text);
CREATE TABLE notifications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, type varchar(40) NOT NULL, payload jsonb NOT NULL DEFAULT '{}', read_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE refresh_tokens (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, token_hash text NOT NULL UNIQUE, expires_at timestamptz NOT NULL, revoked_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX idx_profiles_discover ON profiles(hidden,gender,birth_date) WHERE onboarding_complete=true;
CREATE INDEX idx_photos_user ON photos(user_id,position);
CREATE INDEX idx_likes_target ON likes(to_user_id,created_at DESC);
CREATE INDEX idx_matches_a ON matches(user_a_id,created_at DESC) WHERE unmatched_at IS NULL;
CREATE INDEX idx_matches_b ON matches(user_b_id,created_at DESC) WHERE unmatched_at IS NULL;
CREATE INDEX idx_messages_conversation ON messages(conversation_id,created_at DESC);
CREATE INDEX idx_notifications_user ON notifications(user_id,created_at DESC) WHERE read_at IS NULL;
CREATE INDEX idx_refresh_user ON refresh_tokens(user_id,expires_at) WHERE revoked_at IS NULL;
INSERT INTO interests(name) VALUES ('Travel'),('Coffee'),('Design'),('Live music'),('Hiking'),('Cooking'),('Photography'),('Books') ON CONFLICT DO NOTHING;
